// F10: one forwarded review notification per mail. PocketBase finds the hotel
// from its unguessable address (r-<token>@ZARIN_REVIEWS_MAIL_DOMAIN), parses the
// mail and keeps only the review; nothing of the mail is stored in n8n beyond
// its execution log (keep execution data short: EXECUTIONS_DATA_MAX_AGE).
// An auto-forwarded mail keeps its original To:, so the delivery headers count too.
const domain = String($env.ZARIN_REVIEWS_MAIL_DOMAIN || '').toLowerCase();
const list = (v) => {
  if (!v) return [];
  if (typeof v === 'string') return v.split(',');
  if (Array.isArray(v)) return v.flatMap(list);
  if (Array.isArray(v.value)) return v.value.map((a) => a.address || '').filter(Boolean);
  if (v.text) return String(v.text).split(',');
  return [];
};
return $input.all().flatMap((item) => {
  const m = item.json;
  const h = m.headers || {};
  const to = [
    ...list(m.to), ...list(m.cc),
    ...list(h['delivered-to']), ...list(h['x-original-to']), ...list(h['x-forwarded-to']),
  ].map((a) => String(a).trim()).filter(Boolean);
  // Mail not sent to the reviews domain is not ours to send on.
  if (domain && !to.some((a) => a.toLowerCase().includes('@' + domain))) return [];
  const date = m.date ? new Date(m.date) : null;
  const text = String(m.text || '').slice(0, 500000);
  return [{ json: { requestBody: {
    to,
    from: typeof m.from === 'string' ? m.from : (m.from && m.from.text) || '',
    subject: String(m.subject || '').slice(0, 500),
    date: date && !isNaN(date.getTime()) ? date.toISOString() : '',
    text,
    html: text ? '' : String(m.html || m.textAsHtml || '').slice(0, 500000),
    messageId: String(m.messageId || ''),
  } } }];
});

// Signs a request for the Zarin Integration API.
// With ZARIN_KEY_ID and ZARIN_KEY_SECRET set (a scoped key from `npm run integration-key`):
//   HMAC-SHA256(keySecret, `${timestamp}.${nonce}.${body}`), a fresh nonce per request (v2).
// Otherwise the shared secret: HMAC-SHA256(ZARIN_INTEGRATION_SECRET, `${timestamp}.${body}`) (v1).
// Requires NODE_FUNCTION_ALLOW_BUILTIN=crypto on the n8n instance.
const crypto = require('crypto');
const keyId = $env.ZARIN_KEY_ID || '';
const keySecret = $env.ZARIN_KEY_SECRET || '';
const scoped = Boolean(keyId && keySecret);
const sign = (json) => {
  const body = json.requestBody ? JSON.stringify(json.requestBody) : '';
  const timestamp = Math.floor(Date.now() / 1000);
  const nonce = scoped ? crypto.randomBytes(16).toString('hex') : '';
  const signature = crypto
    .createHmac('sha256', scoped ? keySecret : $env.ZARIN_INTEGRATION_SECRET)
    .update(scoped ? `${timestamp}.${nonce}.${body}` : `${timestamp}.${body}`)
    .digest('hex');
  return { ...json, rawBody: body, zarinTimestamp: String(timestamp), zarinSignature: signature, zarinKeyId: scoped ? keyId : '', zarinNonce: nonce };
};
return $input.all().map((item) => ({ json: sign(item.json) }));
